    Returns a 321-like Number.
    """
    # Check if N is a 321-like Number
    if N < 1:
        return False

    # Check if N is a positive integer
    if N < 1:
        return False

    # Check if N is a one-digit positive integer
    if N % 2 == 0:
        return False

    # Check if N is a 321-like Number
    if N % 3 == 0:
        return True

    # Check if N is a 321-like Number
    if N % 4 == 0:
        return True

    return True

