def count_non_empty_substrings(S, N):
    # Initialize a counter to keep track of the number of non-empty substrings
    count = 0

    # Iterate over the string S
    for i in range(N):
        # Check if the current character is the same as the character in the substring
        if i == S[i]:
            # If the current character is the same as the character in the substring, it's a repetition
            count += 1

    return count

