def find_minimum_value(D):
    if D <= 0:
        return 0

    x, y = D

    for i in range(1, D):
        x = (x**2 + y**2) % D
        y = (y**2 + x**2) % D

        if x**2 + y**2 - D <= 0:
            return x, y

    return 0

