def find_minimum_weight(graph, weights):
    # Initialize a list to store the weights of the edges
    weights = {}
    # Iterate over the edges
    for edge in graph:
        # Check if the edge exists
        if edge in weights:
            weights[edge] += weights[edge]
        # Check if the edge is traversed
        if edge in weights:
            weights[edge] += weights[edge]
    # Find the minimum total weight of the edges traversed
    min_weight = 0
    for edge in weights:
        if edge in weights:
            min_weight += weights[edge]
    return min_weight

